const e={title:"TripReel - Gratis Reisanimatie-app: Zet Foto's Om in Mooie Video's",description:"Maak verbluffende reisvideo's met geanimeerde kaarten en vluchtroutes. Gratis reisanimatie-app met 3D-globe routemapping. Zet je foto's automatisch om in mooie reisvideo's. Privacy eerst, werkt offline.",keywords:"reisanimatie-app, reiskaart-animatie-app, reisroute-animatie-app, vlucht-animatie-app, reismaker, automatische reisvideo, geanimeerde reiskaart, vluchtpad-animatie, reisanimatie, globe-animatie, reis-terugblik-video, foto naar video, reis-highlights, gratis reis-app, offline videomaker, privacy reis-app, camerrol video"},i={logoAlt:"TripReel-logo",appName:"TripReel",howItWorks:"Hoe het werkt",video:"Video",features:"Functies",theApp:"De app"},t={badge:"Maak van foto's reisverhalen",title1:"Je camerarol,",title2:"volledig benut",description:"TripReel maakt automatisch prachtige reisvideos van de locaties op je foto's. Zie je reizen tot leven komen met verbluffende geanimeerde routekaarten en vliegroutes over een 3D-wereldbol, terwijl je gegevens privé en veilig blijven.",secure:"100% veilig",worksOffline:"Werkt offline",globeAlt:"TripReel wereldbol-animatie"},n={title:"Hoe het werkt",subtitle:"Drie eenvoudige stappen om je perfecte reisvideo te maken",step1:{title:"Sta toegang tot foto's toe",description:"Geef TripReel toegang tot je fotobibliotheek. De app leest alleen locatiemetadata, niets anders."},step2:{title:"Automatische reisdetectie",description:"TripReel analyseert locatiemetadata en vindt intelligent je reizen op basis van datums en locaties."},step3:{title:"Genereer je video",description:"Kijk hoe je reis zich ontvouwt op een prachtige wereldbol-animatie, klaar om te delen op sociale media."}},a={title:"Zie de magie gebeuren",subtitle:"Ontdek hoe TripReel je fotobibliotheek transformeert in geweldige reisvideos",caption:"Zo kan je uiteindelijke reisvideo eruitzien"},o={title:"Alles wat je nodig hebt",subtitle:"Krachtige functies ontworpen voor moderne reizigers",twoTap:{title:"Reisvideos met twee tikken",description:"Maak verbluffende reisvideos van je fotobibliotheek met slechts twee tikken. Geen bewerking nodig."},smartTrip:{title:"Slimme reisdetectie",description:"Vindt en groepeert automatisch je reizen door datums en locatiemetadata van je foto's te analyseren."},globe:{title:"Prachtige wereldbol-animatie",description:"Zie je reis tot leven komen met een verbluffende 3D-wereldbol die je geanimeerde reisroutes en vliegroutes over de hele wereld toont."},privacy:{title:"Privacy voorop",description:"Alles wordt verwerkt op je apparaat. Je foto's verlaten nooit je telefoon. Werkt in vliegtuigmodus."},customStyles:{title:"Aangepaste stijlen",description:"Kies uit meerdere aarde-stijlen en aanpassingen die passen bij jouw esthetiek en elke video uniek maken."},manualControl:{title:"Handmatige bediening",description:"Je kunt handmatig volledig nieuwe reizen toevoegen als locatieservices niet waren ingeschakeld op je apparaat."}},r={title:"Creatieve video-ideeën",subtitle:"Laat je inspireren door wat je kunt maken met TripReel. Van snelle weekendtrips tot jaar durende avonturen, maak verbluffende reisvideos voor elke reis.",description:"Of je nu een reiskaart-animatie maakt, een vluchtroute documenteert of een jaarlijks reisoverzicht samenstelt, TripReel maakt het moeiteloos om je herinneringen om te zetten in deelbare videos.",ideas:{yearRecap:{title:"2025 reisoverzicht",description:"Maak automatisch je jaarlijkse reisoverzicht voor 2025"},europeRoadTrip:{title:"Europese roadtrip",description:"Laat je Europese avontuur zien met geanimeerde routekaarten"},southeastAsia:{title:"Zuidoost-Azië reis",description:"Visualiseer je backpackroute door meerdere landen"},japanRail:{title:"Japan treinreis",description:"Maak kaartvideos van je treinroutes door Japan"},crossCountry:{title:"Dwars door de VS",description:"Verander je Amerikaanse roadtrip in een epische routevideo"},islandHopping:{title:"Eilandhoppen",description:"Toon je reizen van eiland naar eiland met verbluffende 3D-animaties"},worldTour:{title:"Wereldreis montage",description:"Meerdere reizen in één geweldige wereldreis-video"},travelPlans:{title:"Reisplannen voor 2026",description:"Visualiseer en plan je spannende reisavonturen voor 2026"},lifetimeTravel:{title:"Levenslang reisverhaal",description:"Maak een video met al je levenslange reizen"},regionalExplorer:{title:"Regionale verkenner",description:"Breng je avonturen in kaart door staten, provincies en regio's"},festivalCircuit:{title:"Festivalcircuit",description:"Breng je muziekfestival- en evenementenreis in kaart"},bikeRoutes:{title:"Mijn stedentrips",description:"Laat al je stedelijke escapades zien"}}},s={title:"De app",subtitle:"Nu beschikbaar op de App Store",alt1:"Automatische reisvideos - Maak verbluffende videos in enkele seconden",alt2:"Foto-locatiedetectie - Gebruikt de metadata van je foto's",alt3:"Reisdetectie - Groepeert automatisch je reizen",alt4:"Prachtige aarde-videos - Wereldbol-animatie van je reis",alt5:"Aangepaste stijlen - Personaliseer je reisvideos"},l={comingSoon:"Binnenkort",androidTitle:"Android-app komt binnenkort!",androidMessage:'De Android-versie is nog niet beschikbaar maar komt binnenkort. Stuur me een bericht op <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> en ik laat je weten wanneer het klaar is!',gotIt:"Begrepen!"},d={title:"Veelgestelde vragen",subtitle:"Alles wat je moet weten over TripReel",q1:{question:"Kan ik de app echt volledig gebruiken in vliegtuigmodus?",answer:"Ja! Voor premium-gebruikers kan de app volledig offline worden gebruikt in vliegtuigmodus zonder beperkingen. Voor niet-premium gebruikers worden sommige functies ondersteund door advertenties waarvoor mogelijk tijdelijk internet nodig is, maar voor premium-gebruikers zijn er geen advertenties en kan de app volledig worden gebruikt in vliegtuigmodus."},q2:{question:"Ik heb geüpgraded naar Premium, hoe kan ik het watermerk verwijderen?",answer:"Veel mensen vragen welke app is gebruikt om deze videos te maken, dus na upgraden naar premium heb je de optie om een kleinere versie van het watermerk toe te voegen (alleen met de app-naam) of het volledig te verwijderen als je dat wilt."},q3:{question:"Zijn mijn fotogegevens veilig en privé?",answer:"Absoluut! TripReel leest alleen locatiemetadata van je foto's - we hebben nooit toegang tot, slaan op of verzenden de daadwerkelijke foto-inhoud. Alle verwerking gebeurt lokaal op je apparaat, en er verlaten nooit gegevens je telefoon. Je kunt dit verifiëren door de app in vliegtuigmodus te gebruiken - het werkt perfect offline!"},q4:{question:"Wat als mijn foto's geen locatiegegevens hebben?",answer:"Geen probleem! Als locatieservices niet waren ingeschakeld toen je je foto's maakte, kun je handmatig reizen maken en zelf locaties toevoegen. De app geeft je volledige controle om je reistijdlijn aan te passen."},q5:{question:"Hoe detecteert de app automatisch mijn reizen?",answer:"TripReel analyseert de locatiemetadata en tijdstempels van je foto's om intelligent te identificeren wanneer en waar je hebt gereisd. Het groepeert nabijgelegen locaties en datums samen om automatisch je reizen te detecteren zonder handmatig werk."},q6:{question:"Kan ik het uiterlijk van mijn videos aanpassen?",answer:"Ja! Je kunt kiezen uit meerdere aarde-stijlen en verschillende aspecten van je geanimeerde reisvideos aanpassen om te passen bij je persoonlijke esthetiek. Premium-gebruikers krijgen toegang tot extra route-animatiestijlen, kaartthema's en vluchtroute-opties."},q7:{question:"Moet ik een account aanmaken?",answer:"Geen account nodig! TripReel werkt meteen na het downloaden. Er is geen registratie, geen login en geen persoonlijke informatie nodig. Download gewoon de app en begin meteen met het maken van je reisvideos."},q8:{question:"Waarom ontbreekt een locatie in mijn reis?",answer:"De app kan alleen werken met beschikbare gegevens, dus ten eerste heb je minstens een paar foto's op die locatie nodig. Ten tweede moet je ervoor zorgen dat je locatiegegevens had ingeschakeld toen je daar was. Ten derde kan slechte GPS-ontvangst soms verkeerde locatiegegevens veroorzaken. Als je dit allemaal hebt uitgesloten en je locatie nog steeds niet verschijnt, kun je die locatie handmatig toevoegen via Reisoverzicht > Bewerken-knop. Gebruik ook Contact om het probleem te melden."},q9:{question:"Waar kan ik mijn geweldige video delen?",answer:"Natuurlijk kun je het ook delen op alle sociale platforms. Om beter bij het platform te passen, staat de app verschillende beeldverhoudingen toe voor je videos."},q10:{question:"Waar kan ik een bug melden?",answer:"Neem gewoon direct contact met me op via marian@qod.ee en leg kort uit wat het probleem is."}},p={title:"E-mailondersteuning",description:"Als je feedback hebt of problemen ondervindt, neem dan gerust rechtstreeks contact met me op via deze e-mail en ik zal persoonlijk je verzoek zo snel mogelijk lezen en behandelen. Bedankt voor het gebruik van de app!",close:"Sluiten"},m={default:{title:"🍪 Cookies",message:"We gebruiken cookies op de TripReel-site om je ervaring te verbeteren. Er worden geen persoonlijke gegevens verzameld.",accept:"Accepteren",decline:"Weigeren",details:"Details"},theme:{title:"🍪 Cookies",message:"🌙 Om je themavoorkeur op te slaan, moet je essentiële cookies accepteren op de TripReel-site. Zonder deze cookies kan je themakeuze niet worden opgeslagen.",accept:"Accepteren",decline:"Weigeren",details:"Details"}},g={privacy:"App-privacybeleid",cookies:"Site-cookiebeleid",contact:"Contact",cookiePreferences:"Cookie-voorkeuren",madeWith:"Gemaakt met",forTravelers:"voor reizigers wereldwijd",copyright:"© {{year}} TripReel."},v={title:"Klaar om je reis te delen?",description:"Download TripReel vandaag en transformeer je camerarol in prachtige reisvideos met geanimeerde kaarten en routes. Je avonturen verdienen het om gevierd te worden.",features:"Gratis te downloaden • Snel en handig • Privacy gegarandeerd"},k={meta:e,header:i,hero:t,howItWorks:n,videoSection:a,features:o,videoIdeas:r,screenshots:s,appStore:l,faq:d,contact:p,cookieBanner:m,footer:g,cta:v};export{l as appStore,p as contact,m as cookieBanner,v as cta,k as default,d as faq,o as features,g as footer,i as header,t as hero,n as howItWorks,e as meta,s as screenshots,r as videoIdeas,a as videoSection};
